(() => {'use strict';const g=()=>window.gameDebug,$=id=>document.getElementById(id);
const steps=['Возьмите настенный факел в руку и зажгите его.','Откройте дверь в тренировочный зал.','Подойдите с горящим факелом к нише и осмотрите её.','Заберите находку из тайника.','Вернитесь к Эллен и расскажите о находке.'];
function start(){const game=g();if(game.state.world){game.tell('Этот сценарий доступен только в мастерской.');return;}if(game.busy||game.state.combat){game.tell('Сначала завершите бой.');return;}stop(false);game.enterScene('hub');const s=game.state;s.trial={step:0,actor:s.active,fixtures:JSON.parse(JSON.stringify(s.lightFixtures)),door:s.doors['hub:door']};s.doors['hub:door']=false;s.trialLetter=false;for(const l of game.scene.lights.filter(l=>l.kind==='wall'&&l.x>12))s.lightFixtures['hub:'+l.fixtureId]={present:true,lit:false};s.trial.fixture=game.scene.props.find(p=>p.type==='torch'&&p.lightId==='west').id;s.lightFixtures['hub:'+s.trial.fixture]={present:true,lit:true};game.tell('Проверка «Свет и тайник»: возьмите факел, откройте дверь и найдите нишу.');window.viewsDebug.switchTab('map');render();game.save();game.render();}
function stop(message=true){const game=g(),s=game.state,t=s.trial;if(!t)return;for(const l of World.scenes.hub.lights.filter(l=>l.kind==='wall'&&l.x>12)){const k='hub:'+l.fixtureId;const present=Torches.fixture(l.fixtureId,'hub').present;s.lightFixtures[k]={present,lit:present&&(t.fixtures[k]?.lit??true)};}if(s.scene==='hub'&&s.party.some(a=>a.x===12&&a.y===7))s.doors['hub:door']=true;else if(t.door===undefined)delete s.doors['hub:door'];else s.doors['hub:door']=t.door;delete s.trial;if(message){game.tell('Проверка завершена. Освещение зала восстановлено.');game.save();game.render();}}
function advance(){const t=g().state.trial;if(!t||t.step>=5)return;const a=g().state.party.find(p=>p.id===t.actor);if(t.step===0&&!Torches.fixture(t.fixture,'hub').present&&a.torches&&a.hands.includes('torch')&&a.torch)t.step=1;if(t.step===1&&g().state.doors['hub:door'])t.step=2;}
function interact(p){const game=g(),t=game.state.trial,a=game.active();if(!t){game.tell('Запустите «Свет и тайник» во вкладке «Тест».');game.render();return;}advance();if(game.state.combat||a.id!==t.actor||t.step<2){game.tell('Сначала выполните текущий шаг проверки выбранным героем.');game.render();return;}if(t.step===2){if(!a.torch||!a.hands.includes('torch')){game.tell('Для осмотра ниши возьмите горящий факел в руку.');game.render();return;}t.step=3;game.tell('В свете факела видна щель за старой доской. Внутри лежит письмо Эллен.');}else if(t.step===3){t.step=4;t.letter=true;game.state.trialLetter=true;game.tell('Вы взяли письмо. Теперь вернитесь к Эллен.');}else game.tell('Ниша пуста. Эллен ждёт у своего стола.');game.save();game.render();}
function talk(){const t=g().state.trial;if(t?.step===4&&g().state.scene==='hub'&&g().active().id===t.actor&&Math.abs(g().active().x-6)+Math.abs(g().active().y-3)===1){t.step=5;g().tell('Эллен узнаёт письмо: «Спасибо. Теперь я знаю, где искать пропавший колокол». Проверка пройдена.');g().save();g().render();}}
function goal(){const t=g().state.trial;if(!t)return null;if(t.step===0)return g().scene.props.find(p=>p.id===t.fixture);if(t.step===1)return g().scene.props.find(p=>p.id==='door');if(t.step===2||t.step===3)return g().scene.props.find(p=>p.id==='trial-cache');if(t.step===4)return g().scene.props.find(p=>p.id==='keeper');return null;}
function render(){const game=g();if(!game)return;advance();const panel=$('trial-panel'),t=game.state.trial;panel.hidden=!t;if(!t)return;$('trial-step').textContent=t.step===5?'Проверка пройдена · 5 / 5':'Свет и тайник · '+(t.step+1)+' / 5';$('trial-hint').textContent=t.step===5?'Факел, дверь, осмотр, находка и диалог проверены.':steps[t.step];$('trial-focus').hidden=t.step===5;$('trial-focus').onclick=()=>{if(game.state.scene!=='hub'){game.tell('Вернитесь в ателье, чтобы продолжить проверку.');return;}const p=goal();if(p){game.select(p);window.camera?.center(p);}};$('trial-stop').onclick=()=>stop();}
window.Scenario={start,stop,render,interact,talk,goal};})();
